export function getAllPackages(): Package[] {
  return authoritativePackages;
}

export function getFeaturedPackages(limit: number = 3): Package[] {
  const featured = authoritativePackages.filter(p => p.featured);
  if (featured.length >= limit) return featured.slice(0, limit);
  return authoritativePackages.slice(0, limit);
}

export function getPackageBySlug(slug: string): Package | undefined {
  return authoritativePackages.find(p => p.slug === slug);
}

export function getPackagesByDestination(destination: string): Package[] {
  return authoritativePackages.filter(
    p => p.destination.toLowerCase() === destination.toLowerCase()
  );
}

export function getPackageTables(slug: string): PackageTableData | null {
  const data = (packageTablesData as Record<string, PackageTableData>)[slug];
  return data || null;
}

// Verified destinations outside India in the authoritative MTPL catalogue
export const INTERNATIONAL_DESTINATIONS = new Set([
  'Bhutan',
  'Nepal',
  'Sri Lanka',
  'Jordan',
  'Cambodia',
  'Dubai',
  'Japan',
]);

export function getPackageCategory(pkgOrDestination: Package | string): PackageCategory {
  if (typeof pkgOrDestination === 'object' && pkgOrDestination.category) {
    return pkgOrDestination.category;
  }
  const dest = typeof pkgOrDestination === 'string' ? pkgOrDestination : pkgOrDestination.destination;
  return INTERNATIONAL_DESTINATIONS.has(dest) ? 'international' : 'national';
}

export function getPackagesByCategory(category: PackageCategory): Package[] {
  return authoritativePackages.filter(p => getPackageCategory(p) === category);
}

